import{_ as r,o as a,c as t,ag as o}from"./chunks/framework.B_zcDAFh.js";const m=JSON.parse('{"title":"Boing Reactor Field Sampler","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor-field-sampler.md","filePath":"guide/boing-reactor-field-sampler.md"}'),i={name:"guide/boing-reactor-field-sampler.md"};function s(l,e,n,d,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="boing-reactor-field-sampler" tabindex="-1">Boing Reactor Field Sampler <a class="header-anchor" href="#boing-reactor-field-sampler" aria-label="Permalink to &quot;Boing Reactor Field Sampler&quot;">​</a></h1><p>A <strong>Boing Reactor Field Sampler</strong> reads from a <a href="./boing-reactor-field.html">Boing Reactor Field</a> and applies the field&#39;s influence to the object it&#39;s attached to. Instead of each object being pushed directly by effectors, the field&#39;s &quot;proxy grid&quot; absorbs the disturbance once and many sampler objects then read from it.</p><p>Two sampler variants are provided:</p><ul><li><strong>CPU Sampler</strong> (<code>BoingReactorFieldCPUSampler</code>) — reads on the CPU and writes the result to the object&#39;s transform.</li><li><strong>GPU Sampler</strong> (<code>BoingReactorFieldGPUSampler</code>) — reads on the GPU inside the vertex shader, suitable for instanced meshes or large vertex counts.</li></ul><h2 id="gpu-sampler-requirements" tabindex="-1">GPU Sampler Requirements <a class="header-anchor" href="#gpu-sampler-requirements" aria-label="Permalink to &quot;GPU Sampler Requirements&quot;">​</a></h2><p>If you use the GPU sampler, the object&#39;s material must use a shader whose vertex stage calls one of:</p><ul><li><code>ApplyBoingReactorFieldPerObject</code></li><li><code>ApplyBoingReactorFieldPerVertex</code></li></ul><p>Boing Kit ships example shaders (modified from Unity&#39;s standard shader) that already wire these in correctly. To add support to a custom vertex shader, look at the <strong>Example Custom Shader</strong> files inside the <em>Warped Teapots</em> example.</p><h2 id="scriptable-render-pipelines" tabindex="-1">Scriptable Render Pipelines <a class="header-anchor" href="#scriptable-render-pipelines" aria-label="Permalink to &quot;Scriptable Render Pipelines&quot;">​</a></h2><p>For URP and HDRP, the same shader hooks apply but live inside shader graphs. Boing Kit provides a <strong>shader subgraph</strong> (under <code>Shader/</code>) that wraps the helper functions, which you can drop into your own URP/HDRP graphs.</p>',10)])])}const u=r(i,[["render",s]]);export{m as __pageData,u as default};
